#!/usr/bin/env python3
"""Author fresh ER13 inputs only. Never dispatch, score, or reveal candidate plans."""
import hashlib, json
from datetime import datetime, timezone
from pathlib import Path
BASE=Path(__file__).resolve().parents[2]/'inputs'
TIME=('Complete all substantive research and planning obligations within a maximum of 60 elapsed minutes. '
      'Finish earlier when the complete output is ready. There is no minimum research duration, no requirement '
      'to consume the allowance, and no credit for waiting. The deadline includes arm-specific setup, provider '
      'queueing after admission, tools, native retries, handoffs, revision and delivery. Output quality is assessed '
      'independently of elapsed time.')
DISCOVERY=('Produce a research-backed software proposal, not an implementation. Explore relevant primary documentation, '
           'repository code, callers/tests, and issue-to-fix or release history where consequential. Compare feasible '
           'alternatives without assuming a winning product. Distinguish proposed validation from work actually executed. '
           'The exact draft plan is withheld during brief-only discovery and released once at the declared comparison point.')
CASES=[]
def case(cid,title,scope,families,brief,plan,obligations,negatives,alternatives,validation):
    brief=f'# {title}\n\n{brief.strip()}\n\n{DISCOVERY}\n\n{TIME}\n'
    plan=f'# Draft plan: {title}\n\n{plan.strip()}\n\nThis is a provisional draft for review after the declared reveal, not an endorsed answer. Resolve material assumptions through applicable primary evidence; retain open user-data questions when they cannot be answered from sources. No future product deployment is requested.\n\n{TIME}\n'
    for label,txt in [('brief',brief),('plan',plan)]:
        n=len(txt.split())
        if not 200<=n<=400: raise ValueError((cid,label,n))
    rubric={
      'schema_version':'er13-obligation-rubric-v1','case_id':cid,'visibility':'hidden_until_declared_plan_reveal',
      'scoring_policy':'Judge supported meaning and applicability, not length, citation counts, agreement, or token copying. Unknown user data may remain unknown; available mechanism research must still be done.',
      'axes':[
        {'axis':1,'name':'material_original_obligations','criteria':obligations,'negative_constraints':negatives},
        {'axis':2,'name':'consequential_source_facts_and_applicability','criteria':['Check consequential mechanisms against relevant primary context, including platform/version and caller or integration boundaries.','Separate documented guarantees from assumptions and limits.']},
        {'axis':3,'name':'useful_unfamiliar_discovery_alternatives_history','criteria':alternatives,'record':['Useful supported opportunities','Material missing mechanism families'],'recall_limit':'Observed finite comparison set only; no universal recall claim.'},
        {'axis':4,'name':'valid_corrections_rejections_plan_dispositions','criteria':['After reveal, disposition each material draft choice as retained, changed, rejected, or unresolved with consequential support.','Do not silently discard requested behavior when correcting a draft assumption.']},
        {'axis':5,'name':'supported_meaning_retained_to_complete_final','criteria':['Preserve all material requirements and justified findings from discovery, draft and criticism in the complete final.','Keep alternatives, exceptions, negative constraints and uncertainty visible where they affect decisions.']},
        {'axis':6,'name':'meaningful_validation_with_execution_distinguished','criteria':validation+['Identify which checks were executed, what they observed and their limits; label all unexecuted checks as proposed.','Research-proposal scope does not require deployment, physical intervention or proof of all possible behavior.']}
      ],
      'time_contract':{'maximum_elapsed_minutes':60,'minimum_duration':None,'quality_independent_of_elapsed':True,'wording':TIME},
      'global_negative_constraints':['Do not deploy the future product.','Do not write canonical product specifications.','Do not preselect a winning product.','Do not expose this rubric or exact draft plan during brief-only discovery.']}
    metadata={'schema_version':'er13-case-metadata-v1','case_id':cid,'title':title,'pipeline':'FULL','mission':'SOFTWARE','brief_scope':scope,'mechanism_families':families,'fresh':True,'treatment_specific':False,'maximum_elapsed_minutes':60,'minimum_duration':None,'discovery_inputs':['brief.md'],'reveal_inputs':['plan.md'],'evaluation_inputs':['rubric.json'],'plan_reveal':'once_at_declared_comparison_point_after_brief_only_discovery','validation_status':'No candidate research, product implementation, deployment, or validation execution performed by case author.','files':{'brief':'brief.md','plan':'plan.md','rubric':'rubric.json'},'word_counts':{'brief':len(brief.split()),'plan':len(plan.split())}}
    folder=BASE/cid
    folder.mkdir(parents=True,exist_ok=True)
    for name,content in [('brief.md',brief),('plan.md',plan),('rubric.json',json.dumps(rubric,indent=2)+'\n'),('metadata.json',json.dumps(metadata,indent=2)+'\n')]:
        target=folder/name
        if target.exists() and target.read_text()!=content: raise FileExistsError(f'Refusing to replace different existing case bytes: {target}')
        target.write_text(content)
    CASES.append(metadata)

def manifest():
    rows=[]
    for m in CASES:
        files={}
        for name in ['brief.md','plan.md','rubric.json','metadata.json']:
            p=BASE/m['case_id']/name
            files[name]={'path':str(p.relative_to(BASE)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size,'visibility':'brief_only_discovery' if name=='brief.md' else 'dispatcher_only_metadata' if name=='metadata.json' else 'hidden_until_declared_reveal'}
        rows.append({'case_id':m['case_id'],'scope':m['brief_scope'],'mechanism_families':m['mechanism_families'],'pipeline':'FULL','files':files})
    d={'schema_version':'er13-design-manifest-v1','case_author':'codex-er13-design','cases':rows,'software_cases':len(rows),'component_level_software_cases':sum(m['brief_scope']=='component' for m in CASES),'hidden_boundary':'Only brief.md enters discovery; exact plan.md released once by root at declared comparison point; rubric remains evaluation-only unless root explicitly declares a later boundary.','time_contract':TIME,'dispatch_and_git_owner':'codex-er13-root'}
    (BASE/'MANIFEST.json').write_text(json.dumps(d,indent=2)+'\n')
    (BASE/'MANIFEST.md').write_text('# ER13 fresh design inputs\n\n'+ '\n'.join(f"- {m['case_id']}: FULL software pipeline; {m['brief_scope']} brief; {', '.join(m['mechanism_families'])}." for m in CASES)+'\n\nOnly brief.md belongs in initial discovery. plan.md is the hidden provisional draft, released once at root’s declared comparison point. rubric.json is evaluation-only. File hashes and sizes are in MANIFEST.json. Every case has a maximum of 60 elapsed minutes and no minimum duration.\n')

case('A-F01','Disconnected field-survey edit journal','component',['local_data','synchronization'],'''
A regional ecology group already has a desktop survey application. Design its local edit journal and reconnection component for three field laptops that may remain disconnected for a week. Records contain site identifiers, observation notes, a confidence flag, and links to photos stored separately. Two people can edit the same observation while offline; deleting a record and adding a photo can also overlap. The group needs a comprehensible recovery path after a laptop loses power during a save or reconnect.

Research storage and synchronization approaches, identity and conflict representation, attachment references, and a small operator-facing explanation of what needs review. Preserve a recoverable history of competing edits without requiring the user to understand database internals. Assume up to fifty thousand observations per season; actual attachment sizes and connection speeds are unknown. The existing application's language and storage engine are undecided. Do not mandate a hosted account, upload photo contents automatically, resolve every collision by wall-clock time, or let a reconnect silently resurrect a deleted observation. A manual transfer option should remain possible when the network is unavailable. Recommend a bounded integration sequence and realistic failure-oriented validation.
''','''
The draft uses a transactional embedded store for observations and a second append-only journal carrying operation identifiers, author labels, and per-record revision numbers. Photos remain in a directory selected by the operator; journal entries hold relative references and hashes. Each laptop exchanges journal segments through a relay on the office network, with removable-media bundles as a fallback. Nothing requires a hosted account.

For now, the relay accepts operations in arrival order. A revision mismatch opens a conflict card showing the old value and both edits. Nonoverlapping field edits are proposed for automatic merging, while delete-versus-edit is routed to review. The draft assumes that laptop-local revision numbers plus an author label uniquely identify operations, and that acknowledgment permits discarding sent segments. Whether either assumption survives reinstall, lost acknowledgments, and interrupted transfer is unresolved. Wall-clock timestamps are display information, not a winner rule.

Save and journal append should appear atomic to the application. The draft has not yet selected one database transaction or a coordinated file protocol, and attachment copying remains an explicit action. It proposes a retention setting for resolved conflicts but leaves recovery after retention open. Validation would replay duplicate segments, interrupt saves, reconnect after competing deletion and photo addition, and restore a copied store. No checks have been run. A staged proposal should settle identity and durability before adding convenient merge behavior.
''',[
'Local save durability and recovery after power loss; reconnect behavior for week-long disconnection.',
'Concurrent edits, overlapping delete/photo operations, recoverable competing history and intelligible operator review.',
'Separate attachment references, fifty-thousand-record applicability, manual transfer and bounded integration sequence.'
],['No mandatory hosted account.','No automatic photo-content upload.','No wall-clock-only collision resolution.','No silent resurrection of deleted observations.'],['Compare transactional storage/journal coupling alternatives and an appropriate synchronization/conflict model.','Consider relay and removable-media operation without assuming either is sufficient for identity or retention.'],['Propose interruption, duplicate transfer, acknowledgment-loss, reinstall identity and deletion conflict checks.','Explain what store restoration and attachment-integrity checks establish and leave unknown.'])

case('A-F02','Oral-history intake and transcript handoff','component',['import_export_media','accessibility'],'''
A small museum has an existing collection catalog and wants an intake component for donated oral-history recordings. Volunteers receive audio files, a transcript when one exists, and a spreadsheet of recording identifiers and permissions. File extensions are inconsistent, some recordings have two channels with different speakers, and a corrected transcript can arrive after initial intake. Research an intake design that preserves original media and gives catalog staff a previewable, accessible record of what was accepted or rejected.

Cover format identification, metadata and duration extraction, channel handling, transcript-to-record association, safe batch restart, and portable handoff to the catalog. A warning must distinguish unreadable media from unsupported preview, and an absent transcript must not look like failed audio. Staff should be able to operate the review flow by keyboard and obtain meaningful textual status. A batch is usually forty recordings but can reach five hundred; no particular codec or catalog API is fixed. Do not alter original bytes, guess missing usage permissions, send recordings to cloud transcription, or require transcoding every item before it can be cataloged. Compare feasible approaches and explain where format support ends. The deliverable is a research proposal with staged integration and validation, not a migration of the museum's actual collection.
''','''
The draft creates a batch manifest before examining recordings. Each entry stores the donation identifier, original path, permission text supplied by staff, byte hash, and separate probe and preview statuses. Original media are copied to an intake directory without alteration, then a format-probing process reports container, channels and duration. Preview generation is optional; a successfully cataloged original need not have a playable preview.

A transcript is attached when its filename stem matches the recording identifier after lowercasing and removing spaces. Later transcripts replace the current association while preserving the prior file in history. This assumes normalized stems remain unique and the spreadsheet identifier is consistently present; neither condition has been checked. Permission fields can stay unknown and block release rather than being inferred. No cloud transcription is planned.

The proposed interface presents a keyboard-navigable table with text labels for accepted, needs review, unsupported preview and unreadable original. It leaves how progress announcements avoid overwhelming screen-reader users unresolved. Export is a directory with manifest, transcripts and media references; the receiving catalog is assumed to resolve those references after copying the folder. Channel-specific preview and timing alignment need investigation before deciding whether conversion is necessary. Proposed validation covers renamed extensions, interrupted batch restart, corrupt files, stereo speakers, transcript corrections and keyboard/screen-reader review. No collection files have been inspected and no validation has been executed.
''',[
'Identify media, extract metadata/duration, handle channels and preserve original bytes.',
'Associate and revise transcripts with distinct missing-transcript, unreadable-original and unsupported-preview status.',
'Restart batches safely and produce portable catalog handoff with permission uncertainty preserved.',
'Keyboard review and meaningful textual accessibility status; applicability at forty to five hundred recordings.'
],['Do not alter original bytes.','Do not infer missing usage permissions.','No cloud transcription.','Do not require universal transcoding before cataloging.','Do not migrate the actual collection.'],['Compare detection/probing, preview and association approaches with explicit supported-format boundaries.','Consider portable handoff alternatives when no catalog API is fixed.'],['Propose mislabeled/corrupt/channel-varied media, restart and corrected-transcript association checks.','Propose keyboard and screen-reader review plus exported-reference relocation checks; no actual collection intervention required.'])

case('B02-P01','Accessible command selection in a desktop editor','component',['accessibility','search_knowledge'],'''
An existing technical writing editor needs a searchable command chooser for users who cannot reliably use a mouse. Commands include editing actions, document navigation and extension-provided actions. Some commands are unavailable until text is selected; others have the same display label but act in different scopes. Research the component's interaction, command registry and search behavior rather than redesigning the whole editor.

Users must open the chooser from the keyboard, understand an unavailable command's reason, and return to their previous editing position when they dismiss it. Search should tolerate a mistyped query and expose command names, shortcut information and scope without announcing every keystroke as a separate interruption. Extension commands can be added or removed while the chooser is open. Assume Windows and Linux desktop use, including screen readers, but do not assume a particular UI toolkit. Do not steal ordinary typing shortcuts, invoke a command merely because it is highlighted, make color the sole indication of availability, or require extensions to supply executable UI code. Existing shortcuts must continue to work. Propose a small integration plan, a comparison of relevant interaction and search alternatives, and validation that separates keyboard correctness from screen-reader compatibility. We need documented trade-offs, not a claim that one accessibility API guarantees a usable interaction on all platforms.
''','''
The draft adds a registry of stable command identifiers, localized labels, scopes, optional shortcuts and an availability callback. Extensions contribute descriptors through the existing host registration boundary, not UI code. Opening the chooser captures the editor's current selection and focus destination. Escape closes it; Enter invokes only the selected command after checking availability again. Existing shortcuts remain registered independently.

Search initially lowercases labels and uses a simple edit-distance threshold. Shortcut text and scope appear beside results. Duplicate labels are disambiguated visually by scope, and disabled commands stay in the list with an explanatory reason. The plan assumes that retaining list items after extension removal is safe until the next query and that a generic accessibility role can expose all descriptions; those assumptions need checking against host lifecycle and platform semantics.

The proposed keyboard model keeps focus in the search input while arrow keys move an active result. A single delayed result-count announcement is intended to reduce chatter. The draft has not decided how active-item changes, unavailable reasons, and shortcut text reach assistive technology, nor whether focus restoration survives document closure. Windows and Linux support must be researched separately. Validation would cover cancellation, dynamic registry changes, duplicate labels, mistyping, rejected invocation and screen-reader navigation. No toolkit experiment or user session has been run. A recommendation should compare focus models and ranking approaches before settling interaction details.
''',[
'Keyboard opening, explicit invocation, cancel/focus/selection restoration and existing shortcut compatibility.',
'Unavailable reasons, duplicate label scope and live extension lifecycle without executable extension UI.',
'Mistyped-query search plus names/shortcut/scope exposure with restrained announcements.',
'Windows and Linux applicability and integration sequence without assuming toolkit accessibility equivalence.'
],['Do not steal ordinary typing shortcuts.','Do not invoke from highlight alone.','No color-only availability status.','No extension executable UI requirement.','Do not redesign the entire editor.'],['Compare focus/active-item interaction models and typo-tolerant ranking alternatives.','Research platform accessibility semantics and dynamic command registration boundaries.'],['Propose shortcut collision, cancel/restore, scope ambiguity, dynamic removal and invocation checks.','Separate keyboard checks, platform screen-reader compatibility and proposed usability sessions.'])

case('B02-P02','Shared workshop booking and equipment readiness','project',['plugin_isolation_scheduling','local_data'],'''
A neighborhood workshop currently uses a wall calendar and several spreadsheets to reserve equipment. Research a small software system for member bookings, staff maintenance holds and the daily readiness view. Members reserve time on a tool, while some jobs also require a trained supervisor and a shared extraction unit. Staff may discover a fault after bookings have already been accepted. The system should show an understandable conflict and preserve the reason when a booking changes.

Cover resource modeling, simultaneous booking attempts, recurring maintenance, canceled or interrupted reservations and practical operation when the workshop's internet connection is down. Staff can use one local workstation; member access may use a browser if that is justified. The membership count is about one hundred, and policy for urgent displacement is not yet settled. Do not assume calendar entries enforce capacity, allow a maintenance hold to disappear through member edits, charge payments, or collect identity documents. Avoid mandatory hosted accounts. Booking history needs enough explanation for staff to resolve disputes without becoming surveillance of workshop activity. Compare simple local and shared deployment approaches, identify unresolved policy decisions, and propose staged adoption plus concurrency and failure validation. No installation in the real workshop or live member data processing is requested.
''','''
The draft proposes a local service with a staff interface and a member browser form on the workshop network. A booking is an interval plus tool, supervisor and extraction-unit identifiers. One transaction checks overlaps and stores all required resources together. The daily view joins bookings with fault and maintenance records. Member edits can cancel their bookings but cannot alter maintenance holds. No payment or identity-document collection is included.

Recurring maintenance is expanded one month ahead. A later fault marks affected bookings as needs review; staff then cancel or move them and record a reason. The draft assumes every tool has capacity one and a supervisor can supervise only one job at a time. It has not established whether those assumptions match actual classes and paired operations. Browser forms cache unsubmitted drafts during outages, but the proposal leaves unclear whether an offline member sees a reliable availability view or can receive a confirmed booking.

Staff can export a dated booking-history report, with names visible only to staff. Retention duration and the policy for urgent displacement remain open. A single staff machine is initially responsible for backup and recovery; remote hosting is an alternative to investigate, not selected. Proposed checks cover competing reservations, partial resource assignment, maintenance horizon rollover, daylight-saving changes and fault handling after acceptance. No live system or data has been used. Adoption should start with staff shadow use before exposing a member booking route.
''',[
'Tool/supervisor/extraction dependencies, simultaneous booking, maintenance recurrence and readiness/fault handling.',
'Explain booking changes and interrupted/canceled reservations; distinguish offline drafts from confirmed capacity.',
'Approximately one hundred members, one staff workstation, practical deployment alternatives and staged adoption.',
'History sufficient for disputes with unresolved displacement and retention policies explicit.'
],['Do not treat calendar entries as capacity enforcement.','Member edits cannot erase maintenance holds.','No payments.','No identity-document collection.','No mandatory hosted accounts.','No workshop installation or live member-data processing.','Do not create activity surveillance.'],['Compare local/shared deployment and resource/recurrence models without preselecting a service.','Investigate offline confirmation limits and alternatives for multi-resource booking.'],['Propose simultaneous requests, transaction failure, fault-after-booking, recurrence and timezone checks.','Propose backup/restore and role/access checks with shadow adoption; label all as unexecuted.'])


case('B03-P01','Incremental search for a research notebook','component',['search_knowledge','local_data'],'''
A desktop research notebook already stores notes, tags and links between notes. Design its indexing component so users can search text, filter by tag and follow a result back to the exact note. Notes may be renamed, edited repeatedly or deleted while an index update is running. Some notes contain copied excerpts in different scripts, and a notebook can have twenty thousand entries. The application must remain useful while indexing catches up.

Research index layout, update scheduling, stable identity, query interpretation and recovery from a broken or outdated index. A saved query should retain its meaning after a note title changes. Explain how users learn that results may be incomplete and how an explicit rebuild avoids blocking editing. The notebook's data store is authoritative; search results must not become a competing copy of note content. Do not send note text to a hosted search service, silently omit indexing failures, treat a filename as permanent identity, or promise language coverage without investigating tokenization behavior. Semantic search is optional and must justify its costs if recommended. Compare viable lexical and indexing approaches, identify which measurements would determine responsiveness, and propose a bounded integration sequence. We need source-backed planning, not a benchmark on private notebooks or a full rewrite of the editor.
''','''
The draft maintains a derived index next to the notebook store. Each note carries an internal identifier, title and content revision; updates are queued after the authoritative save. Queries combine free text with a tag filter, and results link through the identifier rather than a path. A saved query stores its query text and filter expression, not a list of current results. No hosted service is planned.

The initial design replaces an indexed document whenever a new revision arrives. A background worker batches requests and reports pending work in the search panel. It assumes that queue order matches save order, even if a slow older update is retried after a newer save. Deleted notes are removed through the same queue; startup reconciles identifiers to detect missed deletions. The plan leaves how to prove revision freshness and how tag changes reach the index unresolved.

Search starts with language-neutral token splitting and case folding, then evaluates whether stemming or another tokenizer improves useful results. A rebuild writes a second index and swaps it in when complete, though simultaneous edits during rebuilding need a concrete handoff rule. Failed records should remain visible in an index-status view. Proposed validation covers rename, repeated edits, delayed retry, deletion, multilingual queries and rebuild interruption. No engine has been selected or performance measured. The proposal should distinguish query semantics, indexing reliability and optional semantic features rather than bundling them into one choice.
''',[
'Text search/tag filters, stable result destinations and saved-query semantics after title changes.',
'Concurrent edits/deletes during indexing, explicit incompleteness and recoverable rebuild while editing.',
'Twenty-thousand-entry applicability, multiple scripts/tokenization and authoritative notebook ownership.'
],['No hosted note-text search.','No silent indexing failures.','No filename-only permanent identity.','No unsupported language-coverage promise.','Semantic search optional, justified if recommended.','No private-notebook benchmarking or editor rewrite.'],['Compare lexical query/tokenization and index-update approaches.','Consider semantic search only as a supported optional trade-off.'],['Propose revision reorder/retry, rename/delete, tag change and concurrent rebuild checks.','Propose representative multilingual query evaluation and responsiveness measurements, distinguishing unmeasured targets.'])

case('B03-P02','Portable project archive export','component',['import_export_media','local_data'],'''
An existing desktop project tracker needs an export component for people who leave a team or keep long-term records. A project contains tasks, comments, dates, custom fields and attached files. Some tasks link to other projects that the exporter cannot access. Users want a portable archive they can inspect without the original application and a structured representation a future importer could use.

Research snapshot consistency, stable identifiers, attachment packaging, text and date representation, schema evolution and safe verification of a completed export. The export should explain omissions rather than implying every link or permission has been preserved. Users may export fifty tasks or fifty thousand; attachments can exceed available temporary disk space. A canceled export must leave the source intact and make incomplete output distinguishable from a finished archive. Do not mutate source records, include inaccessible project content, invent missing attachment bytes, or require internet access to read the human-readable archive. Do not claim round-trip fidelity without defining what is retained. Compare package and streaming approaches and describe reasonable boundaries for a future importer. The requested deliverable is a research-backed design and validation plan; it does not authorize exporting any actual team's records.
''','''
The draft captures a project revision marker, writes task and comment objects into a versioned structured file, then adds attachments and a static readable index. Internal identifiers remain stable, while inaccessible external links are represented by a redacted reference and omission reason. All human-readable assets are local so the archive can be opened without a network connection. Source data remain untouched.

Export initially walks tasks in identifier order and streams attachment bytes into one package. It assumes that reading each task once after taking a revision marker yields a consistent snapshot even if comments change during the walk. Attachment names are sanitized and disambiguated; hashes and original names go into a manifest. Missing bytes yield an omission entry rather than a fabricated file. The proposal has not established how to obtain source snapshots or detect changes when the source store cannot hold a long transaction.

A completion marker is written last, and canceled output is labeled partial. Available temporary space is checked before starting, but the estimation method and streaming container choice remain open. Date values retain their supplied timezone information; custom fields carry type labels plus original values. Round-trip claims would be limited to explicitly mapped fields. Proposed validation covers ongoing edits, inaccessible links, name collisions, interrupted writes, low disk and versioned import fixtures. No export has been executed. A future importer must treat package paths and schema versions as untrusted input.
''',[
'Consistent task/comment/custom-field/date snapshot and stable identifiers.',
'Portable offline readable archive plus structured future-import representation and explicit fidelity boundaries.',
'Attachment packaging/verification, inaccessible-link omissions, scale and low temporary-space handling.',
'Cancellation/source integrity and visibly incomplete output; schema evolution/import boundary.'
],['Do not mutate source records.','Do not include inaccessible project content.','Do not invent attachment bytes.','No internet required for human-readable archive.','No undefined round-trip fidelity claim.','No actual-team export authorization.'],['Compare streaming/container and snapshot consistency approaches.','Consider structured schema evolution and readable output alternatives without selecting a product in advance.'],['Propose concurrent source edits, path/name conflicts, missing attachments, low disk/cancel and complete-marker checks.','Propose versioned fidelity/import checks and untrusted path handling with executed work clearly distinguished.'])

case('B06-P01','Extension isolation for a diagram editor','component',['plugin_isolation_scheduling'],'''
A desktop diagram editor wants third-party extensions that can inspect selected objects, offer a transformation and return proposed changes. The host must stay responsive when an extension loops, crashes or produces an invalid result. Research a component boundary, capability model and update workflow appropriate for extensions maintained by small independent teams.

Extensions may need read access to the active diagram and optional access to a user-selected file. A transformation can add objects but must not silently overwrite edits made while it was running. The proposal should explain how users see permission requests and failed operations without requiring them to understand sandbox internals. Assume Windows and Linux distribution; the host language and extension language are undecided. Do not grant blanket filesystem or network access by default, equate a separate process with a complete security boundary, apply partially validated results to the live diagram, or make the host execute an extension's custom installer. Existing built-in commands should remain available if extension loading fails. Compare viable execution and data-exchange alternatives, including their actual isolation limits and development burden. Recommend a phased integration and validation plan, without installing untrusted extensions or claiming a production security audit.
''','''
The draft runs each extension in a separate process and sends a serialized snapshot of selected objects plus a document revision. Extensions return a proposed patch rather than mutating the diagram directly. The host validates object types, identifiers and allowed operations before presenting a preview. A changed document revision prompts a retry or explicit review, and built-in commands do not depend on extension startup.

A manifest declares file-read and network capabilities. The first version plans to pass only a selected file path and omit network APIs from the extension SDK. It assumes this is sufficient because extensions live outside the host process; actual operating-system restrictions remain unselected. Permission prompts are per extension and remembered locally. The draft does not yet specify whether new versions inherit grants or how a file selector's permission is represented across the boundary.

The host sets a timeout, limits returned patch size and terminates failed workers. Launch overhead and repeated large selections need measurement before choosing per-request or persistent workers. Extension updates are unpacked by host code from a known package format; no custom installers run. Proposed validation includes looping workers, malformed patches, stale revisions, attempted access outside the selected file, blocked network requests and incompatible package upgrades. No extensions have been installed and no isolation test has been executed. A recommendation should separate responsiveness containment from enforceable permission guarantees and identify residual risks.
''',[
'Read-selected-object transformation boundary, patch validation and concurrent-host-edit protection.',
'Loop/crash/invalid-result containment, responsive host and independent built-in commands.',
'Capability/permission UX, optional selected-file access, update workflow and Windows/Linux applicability.'
],['No blanket filesystem/network grants by default.','Separate process alone is not a full security guarantee.','No partial unvalidated live patches.','No execution of custom extension installers.','No untrusted-extension installation or production-audit claim.'],['Compare execution/isolation and data-exchange mechanisms with actual OS limits.','Compare worker lifetime/update permission strategies and developer burden.'],['Propose looping/crashing workers, malformed/stale patches, unauthorized file/network and upgrade-grant checks.','Distinguish responsiveness measurements from enforceable isolation evidence; no production security certification required.'])

case('B06-P02','Volunteer shift handover across unreliable connections','project',['synchronization','search_knowledge'],'''
A volunteer-run food distribution center wants a shared handover system. Teams record tasks, location notes and unresolved equipment problems between shifts. The desk computer normally has a connection, but volunteers often use phones in a loading area with poor reception. A shift leader needs an intelligible summary of what changed and which issues still need attention; a task can be claimed by two volunteers during an outage.

Research end-to-end workflows for reading recent handovers, drafting offline changes, reconciling concurrent updates and searching older issues. Separate a volunteer's acknowledgment that they read a note from a resolution of the underlying issue. Photos are optional and may contain sensitive information; the design should state how attachment upload and deletion work without assuming unlimited mobile data. About thirty volunteers rotate through weekly shifts. Do not turn reading into a performance score, let old offline writes silently reopen resolved issues, expose private contact details in search results, or require a new commercial account for each volunteer. Unknown organizational retention and role policies should remain explicit decisions. Compare synchronization and shared-access alternatives, propose a small adoption sequence and failure-oriented validation. No real volunteer invitations, account creation, deployment or use of live center records is requested.
''','''
The draft uses issue records with stable identifiers, an event history and a separate acknowledgment table. Mobile clients cache the current shift's issues and let volunteers queue comments and task claims while disconnected. A shared service accepts queued events and produces the next shift's summary. Search covers issue titles and notes but excludes contact fields. No reading score or individual productivity ranking is included.

Issue resolution is an explicit event with a reason. The current merge design accepts later comments without changing resolution, while a new task claim on a resolved issue prompts review. It assumes device-generated event identifiers are unique and that queued writes can retain their original access rights until reconnection. Those assumptions need examination when a volunteer leaves a team or two devices share a restored backup. Acknowledgment never resolves the issue.

Photos upload only after an explicit action on a suitable connection. The draft records attachment deletion separately but has not settled cache removal or retention once other phones have downloaded the photo. Access begins with workshop-issued invitation codes; whether those codes establish useful user identity is open. Proposed validation covers two offline claims, stale resolution updates, revoked access, duplicate events, sensitive search fields and deletion across caches. No live records or accounts have been accessed. Adoption would begin with one shift using synthetic examples before policy and attachment questions are closed.
''',[
'Cross-shift reading/summary, offline drafts, concurrent claims and older-issue search.',
'Acknowledgment distinct from issue resolution, stale writes and retained change explanation.',
'Optional sensitive photos, explicit upload/delete/cache behavior and mobile-data limits.',
'Weekly thirty-volunteer context, shared access, retention/roles and staged adoption.'
],['No read-performance scores.','No silent reopening by old offline writes.','No private-contact fields in search.','No mandatory new commercial volunteer accounts.','No invitations, account creation, deployment or live records.'],['Compare synchronization/conflict and shared-access models.','Consider search/cache/attachment retention approaches with unresolved organizational policy explicit.'],['Propose duplicate/two-device writes, offline claims, revoked access and stale-resolution checks.','Propose search confidentiality, explicit upload and multi-cache deletion validation using synthetic data.'])


case('B07-P01','Supplier spreadsheet reconciliation','component',['import_export_media','local_data'],'''
An existing stock-management application needs an import component for supplier spreadsheets. Suppliers send delimited text with inconsistent headers, decimal separators and product codes. Staff must preview changes against current stock records, distinguish a new product from an update and recover from a batch that stops halfway. The source files sometimes repeat a product row or reuse a product code after a discontinued item.

Research parsing, mapping, identity, duplicate handling, transactional application and a comprehensible review workflow. A file can contain up to eighty thousand rows. Staff should save a mapping profile but still see when a new file's structure no longer matches it. Reimporting the same file should not unknowingly add quantities twice. Invalid rows must remain traceable to their source location, and a canceled preview must not change stock. Do not silently coerce ambiguous numbers, treat a supplier code as globally unique, execute spreadsheet formulas, or overwrite staff notes from an unmapped column. Supplier data should stay local. Compare feasible parsing and reconciliation approaches and describe which user decisions are unavoidable. Recommend a staged integration and validation proposal, including what success and partial failure mean. No import of actual supplier data or modifications to the production stock database are requested.
''','''
The draft separates parsing, review and commit. A saved mapping profile identifies headers, supplier identity and expected number conventions. Parsed rows retain their source line and original field text. The preview classifies proposed inserts, updates, duplicates and errors before a transaction applies approved changes. Staff notes are never mapped by default, and formula-like text is treated as data rather than executed.

Identity currently combines supplier identifier with product code. Discontinued items remain in the catalog, but the proposal assumes a matching code still refers to that item unless staff explicitly select a replacement. Quantities are interpreted as absolute stock values; whether suppliers actually send deltas is an open business question. A file hash prevents a second commit of identical bytes, though equivalent resaved files and interrupted retries need further treatment.

The parser chooses locale settings from the saved profile and flags values that do not match. The draft has not established which apparently valid values remain ambiguous or how duplicate rows should be resolved. Commit is all-or-nothing for approved rows, with rejected rows exported in a local review report. At eighty thousand rows, preview memory and transaction duration need investigation. Proposed validation covers reused identifiers, header drift, locale ambiguity, duplicate rows, canceled previews and interrupted commits. No supplier file has been processed. A recommendation should preserve original values and make replacement/delta decisions explicit rather than hiding them inside parsing.
''',[
'Parse/map up to eighty thousand rows with source traceability, header drift and saved profile checks.',
'Distinguish new/update/reused identities and duplicates; establish quantity meaning and reimport safety.',
'Preview cancellation/source protection, approved commit/recovery and intelligible partial-failure outcome.'
],['No silent ambiguous-number coercion.','Supplier code is not globally unique.','No formula execution.','No overwrite of staff notes from unmapped columns.','Keep supplier data local.','No actual supplier import or production modification.'],['Compare parsing/locale and reconciliation/transaction strategies.','Identify unavoidable replacement, duplicate and quantity-delta user decisions.'],['Propose locale/header drift, identifier reuse, duplicate/resaved-file and retry checks.','Propose canceled preview, interrupted commit and memory/transaction measurements with no claimed execution.'])

case('B07-P02','Accessible recording review annotations','component',['accessibility','import_export_media'],'''
A desktop interview editor needs a review component in which staff listen to recordings, mark a time interval and attach a textual comment. The recordings may be long, and reviewers may work entirely from a keyboard or use a screen reader. Several comments can overlap. A transcript, when available, should provide a second route to the relevant passage, but the review workflow must also work when no transcript exists.

Research time representation, seeking and interval editing, annotation identity, transcript association and accessible navigation through comments. A later replacement recording can have a different lead-in or sample rate; existing annotations must not silently point at the wrong passage. Users need to export comments in a human-readable form with useful timing context. Assume local files and occasional stereo recordings; the playback engine is not fixed. Do not require mouse dragging, encode interval distinctions by color alone, invent transcript timings, alter original recordings, or transmit audio to a remote service. A missing transcript must not block a keyboard review. Compare suitable annotation and interaction approaches, state media and timing limits, and propose integration plus validation of both accessible interaction and annotation fidelity. The deliverable does not require recruiting real interview subjects, deploying a player or annotating private recordings.
''','''
The draft stores annotations as stable identifiers with start and end milliseconds, comment text and a recording hash. A keyboard action marks the current playback position; another closes the interval. A list offers navigation to each annotation, overlapping intervals remain separate, and text labels state their ranges. Review is possible without a transcript. Original local audio is never changed or transmitted.

When a transcript supplies timed segments, selecting a segment seeks to its supplied start time. Untimed transcripts are searchable text but do not create inferred timings. The draft assumes milliseconds reported by the playback API are stable enough for annotation round trips across supported formats. It also proposes restoring annotations after a recording replacement when the filename matches, warning only if duration differs. That replacement rule has not been justified, particularly for equal-duration files with changed lead-ins.

Comments export to a static text report with filename, hash and formatted ranges. The draft has not decided whether channel information or an explicit media-relative time basis is necessary. Focus should remain predictable while playback continues, but seek announcements and interval editing need platform-specific accessibility research. Proposed validation covers overlapping annotations, seeking near boundaries, different sample rates, replaced media, transcript absence and keyboard/screen-reader operation. No recordings or assistive-technology sessions have been used. Implementation should first establish annotation/media identity and then integrate the review controls.
''',[
'Keyboard seeking/interval editing, stable overlapping annotations and accessible comment navigation.',
'Optional transcript route without inferred timings; no-transcript workflow.',
'Replacement-media identity/timing safety, local/stereo limits and readable timing-context export.'
],['No required mouse dragging.','No color-only interval distinctions.','Do not invent transcript timings.','Do not alter original media.','No remote audio transmission.','Missing transcript cannot block keyboard review.','No real-subject recruitment, player deployment or private annotations.'],['Compare interval/time representations and accessible interaction patterns.','Investigate seeking/format boundaries and media identity/replacement alternatives.'],['Propose overlap/boundary seek, sample-rate and same-duration replacement checks.','Propose keyboard/screen-reader, absent/untimed transcript and export fidelity checks separately.'])

case('B09-P01','Neighborhood lending inventory and returns','project',['local_data','synchronization','search_knowledge'],'''
A small neighborhood tool library needs software for inventory, lending and returns. Volunteers currently maintain separate lists of items and loans, and duplicate item names make it hard to tell which physical drill or ladder was lent. Research a system that gives each item a durable identity, shows current availability and preserves an explanation when a loan or return is corrected.

Two volunteers may work from separate laptops during a busy session. Internet access is unreliable, but they can normally reach a local network. Some items are lent as kits with removable parts, and a damaged return should create a maintenance hold rather than immediately mark the item available. Search needs to find aliases and distinguish similar items. Contact details should be limited to what is necessary for a loan reminder; the policy for sending reminders is undecided. Do not require paid cloud accounts, infer a return from the passage of a due date, erase loan history when an item is retired, or automatically send borrower messages. About eight hundred items and five years of records are expected. Compare identity, concurrency and deployment approaches, identify organizational policy gaps and propose staged adoption with recovery validation. No deployment, live borrower processing or outbound communication is requested.
''','''
The draft assigns internal item identifiers and printable labels, then records loans and returns as events referencing those identifiers. Item names and aliases are search fields, not keys. A kit is a parent item with a parts checklist; an incomplete or damaged return keeps it in maintenance review. Due dates can flag overdue loans but never imply a return. Retired items remain in history.

A local coordinator is initially the authority for accepted loans. Both laptops read availability from it, and a transaction should prevent simultaneous checkout of the same item. During a disconnected session each laptop can record a provisional loan for later reconciliation. The draft assumes staff will notice those provisional labels and avoid lending a conflicting item, but it has not established an operational rule when the item has physically left before reconnection. Whether offline checkout should be permitted is open.

Borrower contact details are stored separately and only exposed to staff. Reminders are proposed as a staff-reviewed list; nothing sends automatically. Retention and deletion policy, backup ownership and kit-part identity remain unresolved. Proposed validation covers duplicate names, competing checkout, coordinator loss, corrections, incomplete kits, damaged returns and restoration of retired-item history. No borrower records or messages have been accessed. Adoption starts with synthetic inventory and a shadow lending session before replacing the existing lists.
''',[
'Durable physical-item identity, aliases/search, availability and explained corrections/history.',
'Two-laptop concurrency, unreliable internet/local network and recoverable disconnected operation.',
'Kit parts, damaged-return maintenance, retirement history and bounded contacts/reminder policy.',
'Eight-hundred-item/five-year applicability and staged adoption/recovery.'
],['No paid cloud-account requirement.','Due date cannot imply return.','Do not erase history on retirement.','No automatic borrower messages.','No deployment, live borrower processing or outbound communication.','Contact details limited to reminder needs.'],['Compare identity/concurrency and local/shared deployment approaches.','Explore offline lending feasibility and kit/retention policy alternatives without assuming physical conflicts can be undone.'],['Propose simultaneous checkout, coordinator loss/reconciliation, damaged/incomplete kits and correction checks.','Propose history restoration, contact access and shadow adoption checks with unexecuted work labeled.'])

case('B09-P02','Background extension task admission and fairness','component',['plugin_isolation_scheduling'],'''
An existing desktop analysis application allows extensions to submit background tasks for document inspection and report generation. Design its admission and scheduling component so a burst of tasks from one extension does not make the application unusable or starve other work. Some tasks are short and interactive; others consume substantial memory and run for several minutes. The host can obtain declared estimates but cannot assume they are accurate.

Research queue ownership, resource limits, cancellation, progress reporting and safe resumption after a host restart. Users should see why a task is waiting and be able to cancel a queued or running job. A report must be distinguishable from partial output, and canceled tasks must not quietly publish results afterward. Assume Windows and Linux desktop use with variable available memory. Do not equate a concurrency count with a memory bound, require administrator rights, prioritize extensions according to how much they pay, or terminate unrelated user processes. The design should support a useful manual override while explaining its consequences. Compare viable fairness and execution-boundary approaches, and specify which estimates require measurement. Propose phased integration and failure/load validation rather than a full scheduling platform or a deployment in the existing application.
''','''
The draft creates host-owned queue entries with extension identity, task identifier, priority class, estimated memory and a cancellation token. Interactive tasks have a reserved slot, while report tasks share the remaining worker capacity. A per-extension cap prevents one submitter from occupying every slot. The waiting view exposes the limiting reason and allows cancellation or a temporary staff-selected priority increase.

Admission adds declared memory estimates and compares the total with a configurable budget. The draft assumes extensions provide conservative estimates and has not selected an enforceable mechanism when actual usage exceeds them. Workers are separate processes, but operating-system restrictions and what can safely be terminated remain unresolved. Host shutdown records queued jobs and stops owned workers; running jobs are marked interrupted on restart rather than claimed complete.

Report output is written to a task-specific temporary location, then published with a completion record. Cancellation sets the token and eventually terminates an unresponsive owned worker. The plan leaves the race between cancellation and publication unspecified, as well as fairness when continuous interactive work occupies its reserved capacity. No payment priority or administrator requirement is planned. Proposed validation includes estimate underreporting, burst submission, long-job starvation, cancel/publish races, host restart and low-memory behavior. No load experiment has run. The proposal should compare enforceable admission and fairness policies before choosing defaults.
''',[
'Per-extension admission/fairness, interactive/long work, inaccurate estimates and variable memory.',
'Queued/running cancellation, progress/wait explanations and consequential manual override.',
'Interrupted restart, complete/partial output and prevention of late canceled publication.',
'Windows/Linux integration and measurement needs without building a full platform.'
],['Concurrency count alone is not a memory bound.','No administrator-rights requirement.','No payment-based priority.','Do not terminate unrelated user processes.','Canceled tasks cannot silently publish later.','No actual-application deployment.'],['Compare fairness, admission and enforceable execution/resource boundary approaches.','Investigate estimates versus actual usage and manual-override trade-offs.'],['Propose burst/starvation, inaccurate-memory, cancel/publication and host-restart checks.','Propose resource/load measurements limited to owned processes; identify unexecuted work.'])

case('B10-P01','Search provenance for a local technical handbook','component',['search_knowledge','local_data'],'''
An existing engineering handbook stores locally cached copies of public technical documents alongside staff notes. Design a search-result provenance component that helps readers understand which revision supports a claim. A cached document can remain useful while offline, but a new upstream revision may invalidate only part of an older note. Some URLs move or disappear, and staff occasionally import a document manually.

Research revision identity, source relationships, freshness checks and result presentation without assuming that newest always means most applicable. A query may target an older product version deliberately. Users need a clear route from a note excerpt to the supporting cached passage and an explanation when that passage is missing or changed. Network checking should be bounded and optional; offline use must continue. The cache may contain several thousand documents. Do not rewrite staff notes automatically, treat an HTTP timestamp as proof of unchanged content, imply a retrieved page supports every claim in a note, or send private note text upstream. Compare viable provenance and change-detection approaches, state how version-specific evidence is preserved, and propose integration plus validation. We need a source-backed software design, not a historical audit of the actual handbook or an automated crawler of arbitrary sites.
''','''
The draft stores a source URL, retrieval time, supplied product version, byte hash and local document identifier for each cache entry. Notes can link to a document identifier plus a passage selector. Search results display the source revision and whether a later copy has been observed. Older versions remain available when a user filters by product version, and offline reading uses the retained copy.

An optional checker sends conditional requests for known public source URLs. It initially treats a not-modified response as confirmation that all selectors remain valid, while a changed hash marks the document for review. The plan has not established how server validators relate to content or how selector behavior survives different extraction versions. A moved URL records its replacement but does not erase old retrieval history.

Notes are never rewritten automatically, and private note content is not sent to source servers. A changed document should identify affected links, although the proposed passage-diff method remains undecided. Manually imported documents retain their supplied provenance without pretending a network check was possible. Proposed validation covers unchanged response metadata with altered representations, moved URLs, unavailable sources, old-version searches, extraction changes and missing passages. No handbook or crawler has been run. The integration proposal should distinguish retained-document identity from optional network checks and state which failures require user action.
''',[
'Revision/source identity, note-to-cached-passage traceability and missing/changed passage explanations.',
'Offline support, optional bounded freshness checks and version-specific older evidence.',
'Moved/deleted/manual sources, several-thousand-document applicability and consequential change detection.'
],['Do not automatically rewrite staff notes.','HTTP timestamp alone is not unchanged-content proof.','Retrieved page does not imply support for every note claim.','Do not transmit private notes upstream.','Do not assume newest is most applicable.','No actual-handbook historical audit or arbitrary-site crawler.'],['Compare provenance/selector and change-detection approaches.','Examine HTTP validator/extraction/version boundaries using relevant primary context.'],['Propose moved/missing sources, representation/extractor changes, version filters and broken selectors checks.','Propose optional-check bounds/privacy and offline/manual import checks; distinguish executed research from future product validation.'])

case('B10-P02','Portable training handbook with accessible exercises','project',['accessibility','import_export_media','search_knowledge'],'''
A community repair group wants a small training handbook application for volunteers. Authors maintain instructional pages, diagrams and short exercises; learners need offline reading, topic search and a way to record personal exercise progress. The group also shares printable handouts with people who do not install the application. Research a maintainable authoring-to-distribution workflow and the application's basic data boundaries.

Updated lessons should not silently erase a learner's progress or imply that progress on an old exercise proves completion of a materially changed one. Pages must remain navigable by keyboard, with meaningful reading order and text alternatives for instructional diagrams. Search should make lesson versions and retired pages understandable rather than presenting every match as current. Authors sometimes paste material from word processors; investigate import limitations and export fidelity instead of assuming arbitrary formatting survives. Do not require a learner account, upload personal progress, substitute images of text for accessible instructions, or promise print and interactive forms have identical behavior. Include a modest author review step before distribution. Compare authoring/storage and offline/export approaches, identify policy decisions about changed exercises and retired lessons, and propose phased adoption with accessibility and update validation. No publication of training materials, installation for volunteers or processing of actual learning records is requested.
''','''
The draft represents lessons as versioned structured pages with headings, paragraphs, diagrams and exercise identifiers. Authors import supported text and review a rendered preview before creating a distribution package. Learners keep progress in a separate local store; no account or upload is required. Search includes topic terms and a current-or-retired label, while historical lesson versions remain inspectable.

An exercise keeps its identifier across revisions, and the draft initially carries its completed status forward unless the author manually flags a reset. That assumes authors can recognize every material change and that a simple boolean captures enough history. The proposal leaves a policy for edited exercises and retired-page search ranking unresolved. Package updates replace lesson assets but do not replace the learner store.

Keyboard navigation follows headings and explicit links. Diagram text alternatives are authored separately, and exports include a printable handout plus an offline readable version. The plan assumes a shared rendering pipeline can preserve reading order and text alternatives in both outputs; actual format and assistive-technology support need investigation. Imported word-processor formatting may be reduced to supported page structures, with losses shown to authors. Proposed validation covers update interrupted mid-install, progress migration, changed exercise meaning, retired-topic results, pasted tables and keyboard/screen-reader/print review. No lesson package has been published or learner data inspected. Adoption starts with synthetic lessons and one author workflow.
''',[
'Authoring/import-review/distribution flow for pages, diagrams and exercises; offline reading and topic search.',
'Local progress/update separation and truthful treatment of materially changed exercises and retired versions.',
'Keyboard reading/navigation/order, meaningful diagram alternatives and printable/offline export fidelity.',
'Explicit import loss and print/interactive differences, policy decisions and phased adoption.'
],['No learner-account requirement.','No upload of personal progress.','No images-of-text substitute for accessible instructions.','No print/interactive behavior equivalence promise.','Updates cannot silently erase progress or overclaim changed-exercise completion.','No publication, volunteer installation or actual-learning-record processing.'],['Compare authoring/storage and offline/distribution/export representations.','Investigate accessible reading order, format fidelity and version/progress alternatives.'],['Propose interrupted update, progress migration, material exercise revision and retired search checks.','Propose paste-loss review and separate keyboard/screen-reader/print validation with outcomes not invented.'])

